def unique_ids(values):
    seen, result = set(), []
    for value in values:
        if value not in seen:
            seen.add(value)
            result.append(value)
    return result

assert unique_ids([]) == []
assert unique_ids(['a', 'a', 'b']) == ['a', 'b']
